#include <vector>
#include <numeric>
using namespace std;

class Solution {
public:
    bool canThreePartsEqualSum(vector<int>& A) {
        int total = accumulate(A.begin(), A.end(), 0);
        if (total % 3 != 0) return false;

        int target = total / 3;
        int sum = 0, count = 0;

        for (int num : A) {
            sum += num;
            if (sum == target) {
                sum = 0;
                count++;
            }
        }

        return count >= 3;
    }
};
